import { describe, expect, it } from "vitest";
import fr from "./locales/fr/common";
import en from "./locales/en/common";

/**
 * Les mots du lecteur de bande-annonce des téléviseurs (lecteur simplifié) :
 * la barre, « Sous-titres », « Qualité » et leurs panneaux. Ils existent dans
 * les deux langues, et un palier se dit par sa hauteur (« 1080p »).
 */
const KEYS = [
  "trailerTimeline",
  "trailerSubtitles",
  "trailerSubtitlesOff",
  "trailerSubtitleAutoGenerated",
  "trailerQuality",
  "trailerQualityAuto",
  "trailerQualityHeight",
  "trailerNoteTitle",
  "trailerSubtitlesNote",
  "trailerQualityNote",
] as const;

describe("vocabulaire du lecteur de bande-annonce", () => {
  it("existe dans les deux langues", () => {
    for (const key of KEYS) {
      expect(fr[key].trim(), key).not.toBe("");
      expect(en[key].trim(), key).not.toBe("");
    }
  });

  it("dit un palier par sa hauteur", () => {
    expect(fr.trailerQualityHeight.replace("{{height}}", "1080")).toBe("1080p");
    expect(en.trailerQualityHeight.replace("{{height}}", "1080")).toBe("1080p");
  });

  it("dit « Désactivés » pour l'absence de sous-titres", () => {
    expect(fr.trailerSubtitlesOff).toBe("Désactivés");
  });
});
